// Builds the internal "ready for marketing review" email (Apex "simple letter" design, Option C).
const pilotCampaign = 'campaign_test_202609_aac_prestonwood_pilot_2026_09_23';
const isPrestonwoodPilot = $json.campaign_id === pilotCampaign;
if (isPrestonwoodPilot && String($json.doctor_email || '').toLowerCase() !== 'jdold@apexdp.com') {
  throw new Error('The Prestonwood pilot permits only the named test identity.');
}
const escapeHtml = (value) => String(value ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const reviewUrl = String($json.review_url || '');
if (!/^https:\/\/[^\s"'<>]+$/.test(reviewUrl)) throw new Error('The marketing review link is missing or malformed.');
const title = String($json.article_title || 'Article draft');
const doctor = [$json.doctor_name, $json.credentials].filter(Boolean).join(', ');
const practice = String($json.practice_name || '');
// Workflow 21 auto-approves 24 hours after the review was requested (it runs hourly, at quarter past).
const autoApproveAt = $json.auto_approve_at ? new Date($json.auto_approve_at) : null;
const autoApproveText = autoApproveAt && Number.isFinite(autoApproveAt.getTime())
  ? autoApproveAt.toLocaleString('en-US', { timeZone: 'America/Chicago', weekday: 'long', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit' }) + ' CT'
  : '';
const recipient = isPrestonwoodPilot ? 'jdold@apexdp.com' : 'ndorsey@apexdp.com';
const ccList = isPrestonwoodPilot ? '' : 'ballen@apexdp.com, jdold@apexdp.com';
const sharedNote = isPrestonwoodPilot
  ? 'This is the Prestonwood test campaign; only you received this marketing invitation.'
  : 'Sent to Nicole Dorsey, with Brenna Allen and Jake Dold copied. The first decision submitted controls the next step.';
const autoNote = 'If no one approves or requests changes ' + (autoApproveText ? 'by <b style="color:#30302F;">' + escapeHtml(autoApproveText) + '</b>' : 'within 24 hours')
  + ', the article is approved automatically and sent to WordPress (not the live site). The dashboard flags it so the team can give it a closer look before pushing it live.';
const font = "'Montserrat','Segoe UI',Helvetica,Arial,sans-serif";
const assetBase = 'https://apex-content-interviewer.jdold.workers.dev/brand/';
const html = '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Article ready for marketing review</title></head>'
  + '<body style="margin:0;padding:0;background:#f4f6f8;">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f4f6f8;"><tr><td align="center" style="padding:28px 12px;">'
  + '<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:100%;background:#ffffff;border:1px solid #e1e7ec;border-radius:10px;">'
  + '<tr><td style="height:5px;background:#064C78;line-height:5px;font-size:0;border-radius:10px 10px 0 0;">&nbsp;</td></tr>'
  + '<tr><td style="padding:28px 32px 0;font-family:' + font + ';font-size:14px;line-height:1.65;color:#30302F;">'
  + '<p style="margin:0 0 14px;">Hi team,</p>'
  + '<p style="margin:0 0 14px;">An article is ready for marketing review:</p>'
  + '<p style="margin:0 0 4px;font-size:16px;font-weight:700;color:#064C78;">' + escapeHtml(title) + '</p>'
  + ((doctor || practice) ? '<p style="margin:0 0 20px;font-size:13px;color:#6D6E6E;">' + escapeHtml([doctor, practice].filter(Boolean).join(' · ')) + '</p>' : '<div style="height:16px;"></div>')
  + '<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr><td bgcolor="#064C78" style="border-radius:6px;">'
  + '<a href="' + escapeHtml(reviewUrl) + '" style="display:inline-block;padding:13px 26px;font-family:' + font + ';font-size:15px;font-weight:700;color:#ffffff;text-decoration:none;border-radius:6px;">Approve or request changes</a></td></tr></table>'
  + '<p style="margin:18px 0 0;font-size:12px;line-height:1.55;color:#6D6E6E;">' + autoNote + '</p>'
  + '<p style="margin:14px 0 0;font-size:12px;line-height:1.55;color:#6D6E6E;">' + escapeHtml(sharedNote) + '</p>'
  + '<p style="margin:22px 0 0;">Thank you,<br><b style="color:#064C78;">Apex Content Team</b></p></td></tr>'
  + '<tr><td style="padding:24px 32px 26px;"><table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>'
  + '<td style="padding-right:10px;"><img src="' + assetBase + 'email-mark.png" width="30" height="26" alt="Apex" style="display:block;width:30px;height:26px;border:0;"></td>'
  + '<td style="font-family:' + font + ';font-size:11px;line-height:1.4;color:#6D6E6E;border-left:1px solid #cfd9e1;padding-left:10px;">Apex Dental Partners<br><span style="color:#0092C9;font-weight:700;letter-spacing:1px;font-size:9.5px;">PRIVATE PRACTICE REIMAGINED&reg;</span></td>'
  + '</tr></table></td></tr></table></td></tr></table></body></html>';
const text = ['Hi team,', '', 'An article is ready for marketing review:', '', title, [doctor, practice].filter(Boolean).join(' · '), '', 'Approve or request changes: ' + reviewUrl, '',
  autoNote.replace(/<[^>]+>/g, ''), '', sharedNote, '', 'Thank you,', 'Apex Content Team'].join(String.fromCharCode(10));
return { json: {
  article_id: $json.article_id,
  current_version: $json.current_version,
  recipient,
  cc_list: ccList,
  subject: 'Ready for marketing review: ' + title,
  message_html: html,
  message_text: text,
} };

